query MenuItems($restaurantId: String!) {
    menuItems(restaurantId: $restaurantId) {
      id
      name
      description
      sortOrder
      isActive
      tags
      preparationTime
      calories
      prices {
        id
        amount
        currency
        isDefault
      }
      modifierGroups {
        id
        name
        isRequired
        options {
          id
          name
          additionalPrice
        }
      }
    }
  }
